#include <iostream>

int main() {
    short x = 100;  // short has lower rank than int
    unsigned int y = 200;  // unsigned int has same rank as int
    auto result = x + y;  // x is promoted to int, then usual arithmetic conversions apply
    std::cout << "Result: " << result << std::endl;  // Output: 300
    return 0;
}
